      if(b.field==='fills'||b.field==='strokes'){const ps=n[b.field].map(p=>({...p}));ps[b.index||0]=figma.variables.setBoundVariableForPaint(ps[b.index||0],'color',v);n[b.field]=ps;}
      else n.setBoundVariable(b.field,v);
